(()=>{'use strict';const esc=window.AcademyStandard.esc,ids=['design','board','budget','json','contrast'];let scope='preview',current='',output='';const get=(k,d)=>{try{return JSON.parse(localStorage.getItem('dba-extra-'+scope+'-'+k))??d}catch{return d}},save=(k,v)=>{try{localStorage.setItem('dba-extra-'+scope+'-'+k,JSON.stringify(v))}catch{window.AcademyUI.toast('Draft could not be saved. Export it before leaving.')}};
const input=(label,name,val,type='text')=>`<label class="field"><span>${label}</span><input name="${name}" value="${esc(val)}" type="${type}" ${type==='number'?'min="0" max="10000000" step="0.01"':''} required></label>`;
function render(id){current=id;output='';const name=window.AcademyStandard.tools.find(t=>t[0]===id)?.[1];let body='';if(id==='design'){const d=get(id,{title:'A café worth a pause.',body:'Fresh coffee. A clear menu. A warm welcome.\nOpening date to be confirmed.',accent:'#c9260e'});body=`<form id="extra-form">${input('Announcement title','title',d.title)}<label class="field"><span>Approved message</span><textarea name="body" maxlength="1000" required>${esc(d.body)}</textarea></label>${input('Accent color','accent',d.accent,'color')}<button class="btn primary">Update design</button></form><div><div class="design-preview" id="extra-result"></div><button class="btn" data-extra-export>Export SVG design</button></div>`}
if(id==='budget'){const d=get(id,{units:100,price:20,variable:8,fixed:300});body=`<form id="extra-form">${input('Units in this scenario','units',d.units,'number')}${input('Price per unit','price',d.price,'number')}${input('Variable cost per unit','variable',d.variable,'number')}${input('Fixed cost for this period','fixed',d.fixed,'number')}<button class="btn primary">Calculate scenario</button></form><div><div id="extra-result" class="computed-output"></div><p class="small muted">Fictional operating scenario. Keep units and period consistent; this is not accounting or investment advice.</p><button class="btn" data-extra-export>Export calculation</button></div>`}
if(id==='json'){const d=get(id,{text:'{"project":"Café booking","status":"Draft","items":[1,2,3]}'});body=`<form id="extra-form"><label class="field"><span>JSON to inspect</span><textarea name="text" maxlength="250000" class="code-editor" required>${esc(d.text)}</textarea></label><button class="btn primary">Validate & format</button></form><div><pre id="extra-result" class="computed-output"></pre><button class="btn" data-extra-export>Export formatted JSON</button></div>`}
if(id==='contrast'){const d=get(id,{foreground:'#0f1714',background:'#f6f5f1'});body=`<form id="extra-form">${input('Text color','foreground',d.foreground,'color')}${input('Background color','background',d.background,'color')}<button class="btn primary">Measure contrast</button></form><div><div id="extra-result" class="computed-output"></div><p class="small muted">WCAG contrast calculation: normal text requires 4.5:1 for AA; large text requires 3:1. Contrast is one part of accessibility.</p><button class="btn" data-extra-export>Export measurement</button></div>`}
if(id==='board'){body=`<form id="extra-board-form">${input('Task outcome','title','')}${input('Owner','owner','')}<label class="field"><span>Acceptance check</span><textarea name="acceptance" required maxlength="2000"></textarea></label><button class="btn primary">Add task</button></form><div><div id="extra-result"></div><button class="btn" data-extra-export>Export project board</button></div>`}return `<div class="workspace-tabs">${window.AcademyStudio.tools.map(t=>`<a href="#studio/${t[0]}">${window.ToolIcons.icon(t[0],18)}${esc(t[1])}</a>`).join('')}${ids.map(x=>`<a class="${id===x?'active':''}" href="#studio/${x}">${window.ToolIcons.icon(x,18)}${esc(window.AcademyStandard.tools.find(t=>t[0]===x)[1])}</a>`).join('')}</div><section class="panel"><h2>${esc(name)}</h2><p class="small muted">Private practice draft · Saved on this device · Export to keep a copy</p><div class="extra-studio-grid">${body}</div></section>`}
function contrast(a,b){const lum=h=>{const rgb=h.slice(1).match(/../g).map(c=>parseInt(c,16)/255).map(c=>c<=.04045?c/12.92:((c+.055)/1.055)**2.4);return rgb[0]*.2126+rgb[1]*.7152+rgb[2]*.0722};return(Math.max(lum(a),lum(b))+.05)/(Math.min(lum(a),lum(b))+.05)}
function run(){const form=document.getElementById('extra-form'),result=document.getElementById('extra-result');if(!result)return;if(current==='board'){const tasks=get('board',[]);output=JSON.stringify(tasks,null,2);result.innerHTML=tasks.length?tasks.map(t=>`<article class="board-task"><h3>${esc(t.title)}</h3><p>${esc(t.owner)} · ${esc(t.acceptance)}</p><div class="row"><select aria-label="Status of ${esc(t.title)}" data-task-state="${t.id}">${['To do','In progress','Ready for review','Done'].map(s=>`<option ${s===t.status?'selected':''}>${s}</option>`).join('')}</select><button class="text-link" data-delete-task="${t.id}">Remove task</button></div></article>`).join(''):'<p class="muted">Add a task with an owner and observable acceptance check.</p>';return}const data=Object.fromEntries(new FormData(form));save(current,data);if(current==='design'){const title=data.title.slice(0,90),body=data.body.slice(0,1000);result.innerHTML=`<h2 style="color:${data.accent}">${esc(title)}</h2><p>${esc(body)}</p>`;output=`<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="650" viewBox="0 0 1000 650"><rect width="1000" height="650" fill="#f6f5f1"/><path d="M70 70H160" stroke="${data.accent}" stroke-width="6"/><text x="70" y="160" font-family="sans-serif" font-size="42" fill="${data.accent}">${esc(title)}</text>${body.split('\n').slice(0,8).map((line,i)=>`<text x="70" y="${230+i*40}" font-family="sans-serif" font-size="24" fill="#0f1714">${esc(line.slice(0,65))}</text>`).join('')}</svg>`;return}if(current==='json'){output=JSON.stringify(JSON.parse(data.text),null,2);result.textContent=output;return}if(current==='budget'){const {units,price,variable,fixed}=Object.fromEntries(Object.entries(data).map(([k,v])=>[k,Number(v)]));if([units,price,variable,fixed].some(n=>!Number.isFinite(n)||n<0||n>1e7))throw Error('Use non-negative amounts below ten million.');const revenue=units*price,cost=units*variable+fixed;output=`Scenario, not actual results\nUnits: ${units}\nRevenue: ${revenue.toFixed(2)}\nVariable costs: ${(units*variable).toFixed(2)}\nFixed costs: ${fixed.toFixed(2)}\nNet before tax/other costs: ${(revenue-cost).toFixed(2)}\nBreak-even units: ${price>variable?Math.ceil(fixed/(price-variable)):'Not achievable at this unit margin'}`;result.textContent=output;return}if(current==='contrast'){const ratio=contrast(data.foreground,data.background);output=`Contrast: ${ratio.toFixed(2)}:1\nNormal text AA (4.5:1): ${ratio>=4.5?'Pass':'Fail'}\nLarge text AA (3:1): ${ratio>=3?'Pass':'Fail'}`;result.textContent=output;result.style.color=data.foreground;result.style.background=data.background}}
document.addEventListener('submit',e=>{if(!['extra-form','extra-board-form'].includes(e.target.id))return;e.preventDefault();try{if(e.target.id==='extra-board-form'){const d=Object.fromEntries(new FormData(e.target)),tasks=get('board',[]);if(tasks.length>=100)throw Error('This practice board supports up to 100 tasks.');tasks.push({id:crypto.randomUUID(),title:d.title.slice(0,120),owner:d.owner.slice(0,100),acceptance:d.acceptance.slice(0,2000),status:'To do'});save('board',tasks);e.target.reset()}run()}catch(err){document.getElementById('extra-result').textContent=err.message}});
document.addEventListener('input',e=>{if(e.target.closest('#extra-form'))save(current,Object.fromEntries(new FormData(e.target.closest('form'))))});document.addEventListener('change',e=>{if(e.target.dataset.taskState){const tasks=get('board',[]);const t=tasks.find(t=>t.id===e.target.dataset.taskState);if(t){t.status=e.target.value;save('board',tasks);run()}}});
document.addEventListener('click',e=>{const del=e.target.closest('[data-delete-task]');if(del){save('board',get('board',[]).filter(t=>t.id!==del.dataset.deleteTask));run()}if(e.target.closest('[data-extra-export]')){try{run();window.AcademyStudio.download('DigitalBurj-'+current+(current==='design'?'.svg':current==='json'||current==='board'?'.json':'.txt'),output,current==='design'?'image/svg+xml':current==='json'||current==='board'?'application/json':'text/plain')}catch(err){window.AcademyUI.toast(err.message)}}});
window.AcademyExtraStudio={ids,render,mount(){if(document.getElementById('extra-result'))try{run()}catch{}},setScope(id){scope=String(id||'preview').replace(/[^a-zA-Z0-9_-]/g,'').slice(0,100)},contrast};
})();
